import{n as e}from"./rolldown-runtime-Cyuzqnbw.js";import{A as t}from"./framer-Be3hPn0e.js";import{Rn as n,en as r,it as i,t as a,wr as o}from"./icons-DTR6_mEc.js";import{n as s,t as c}from"./ArticleLayout-B2URch02.js";var l,u,d=e((()=>{a(),l=[{"@context":`https://schema.org`,"@type":`Article`,headline:`Rouler en attendant sa carte grise : comment rester assuré pendant les délais`,description:`Carte grise en cours, délais qui s'étirent ? Le certificat provisoire (CPI) vous autorise à rouler 1 mois en France, à condition d'être assuré. L'assurance temporaire vous couvre dès le premier trajet. Attestation en 5 minutes.`,author:{"@type":`Organization`,name:`Evidence Assurances`},publisher:{"@type":`Organization`,name:`AssuTempo`,logo:{"@type":`ImageObject`,url:`https://assutempo.fr/logo.png`}},mainEntityOfPage:`https://assutempo.fr/articles/assurance-temporaire-rouler-en-attendant-carte-grise`,datePublished:`2026-06-03`,dateModified:`2026-07-12`},{"@context":`https://schema.org`,"@type":`BreadcrumbList`,itemListElement:[{"@type":`ListItem`,position:1,name:`Accueil`,item:`https://assutempo.fr`},{"@type":`ListItem`,position:2,name:`Articles`,item:`https://assutempo.fr/articles`},{"@type":`ListItem`,position:3,name:`Rouler en attendant sa carte grise`,item:`https://assutempo.fr/articles/assurance-temporaire-rouler-en-attendant-carte-grise`}]},{"@context":`https://schema.org`,"@type":`HowTo`,name:`Comment s'assurer en attendant sa carte grise en 4 étapes`,totalTime:`PT5M`,step:[{"@type":`HowToStep`,position:1,name:`Choisissez la durée (1 à 90 j)`,text:`Sélectionnez le nombre de jours correspondant à la durée de la transition avant réception de la carte grise définitive.`},{"@type":`HowToStep`,position:2,name:`Renseignez le véhicule (CPI ou carte grise)`,text:`Indiquez les informations du véhicule à partir du certificat provisoire d'immatriculation ou de la carte grise.`},{"@type":`HowToStep`,position:3,name:`Payez en ligne`,text:`Paiement sécurisé par carte bancaire, sans engagement.`},{"@type":`HowToStep`,position:4,name:`Recevez l'attestation (5 min)`,text:`Votre Mémo Véhicule Assuré et votre carte internationale d'assurance automobile arrivent par email.`}]},{"@context":`https://schema.org`,"@type":`FAQPage`,mainEntity:[{"@type":`Question`,name:`Peut-on rouler avec un certificat provisoire ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, le CPI autorise à circuler en France pendant 1 mois, en attendant la carte grise définitive.`}},{"@type":`Question`,name:`Faut-il une assurance avec un CPI ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, la RC est obligatoire dès le premier trajet, quel que soit le statut de la carte grise.`}},{"@type":`Question`,name:`Peut-on s'assurer sans la carte grise définitive ?`,acceptedAnswer:{"@type":`Answer`,text:`Oui, vous pouvez souscrire immédiatement avec le CPI.`}},{"@type":`Question`,name:`Que faire si la carte grise tarde ?`,acceptedAnswer:{"@type":`Answer`,text:`Vérifiez l'avancement sur l'ANTS ; côté assurance, prolongez votre couverture temporaire (jusqu'à 90 jours).`}},{"@type":`Question`,name:`Puis-je rouler à l'étranger avec un CPI ?`,acceptedAnswer:{"@type":`Answer`,text:`Le CPI classique autorise la circulation en France uniquement ; attendez la carte grise définitive pour l'étranger.`}},{"@type":`Question`,name:`Reçoit-on une carte verte ?`,acceptedAnswer:{"@type":`Answer`,text:`Non, elle a été supprimée. Mémo Véhicule Assuré + carte internationale (34 pays) ; contrôle à la plaque via le FVA.`}}]}],u={slug:`assurance-temporaire-rouler-en-attendant-carte-grise`,seo:{title:`Rouler en attendant sa carte grise : comment rester assuré pendant les délais`,description:`Carte grise en cours, délais qui s'étirent ? Le certificat provisoire (CPI) vous autorise à rouler 1 mois en France, à condition d'être assuré. L'assurance temporaire vous couvre dès le premier trajet. Attestation en 5 minutes.`,canonical:`https://assutempo.fr/articles/assurance-temporaire-rouler-en-attendant-carte-grise`,jsonLd:l},category:`Carte grise`,readTime:`4 min`,updatedDate:`12 juillet 2026`,author:`Evidence Assurances`,headline:`Rouler en attendant sa carte grise définitive`,immediateAnswer:`Entre votre demande de carte grise et la réception du titre définitif, vous pouvez rouler grâce au certificat provisoire d'immatriculation (CPI), à condition d'être assuré dès le premier trajet. L'assurance temporaire couvre exactement cette période de transition, sans attendre votre contrat annuel.`,answerCapsule:{answer:`Oui, vous pouvez rouler en attendant votre carte grise : le certificat provisoire d'immatriculation (CPI) délivré par l'ANTS l'autorise pendant 1 mois en France, à condition d'être assuré dès le premier trajet. L'assurance temporaire couvre exactement cette transition.`,facts:[{anchor:`CPI : 1 mois`,text:`Le certificat provisoire autorise à circuler en France uniquement, le temps que le titre définitif arrive par courrier.`},{anchor:`Dès le 1er trajet`,text:`La responsabilité civile est obligatoire quel que soit le statut de la carte grise : rouler sans assurance reste interdit, CPI ou pas.`},{anchor:`Avril 2024`,text:`Plus de carte verte : contrôle à la plaque via le Fichier des Véhicules Assurés (FVA), Mémo Véhicule Assuré et carte internationale (34 pays) par email.`}],updated:`10 juillet 2026`},sections:[{type:`alert`,heading:`L'essentiel`,items:[`Le certificat provisoire d'immatriculation (CPI), délivré par l'ANTS, vous autorise à rouler en France pendant 1 mois, le temps que la carte grise définitive arrive par courrier.`,`L'assurance (RC) est obligatoire dès le premier trajet, indépendamment du statut de la carte grise.`,`L'assurance temporaire couvre la période de transition (1 à 90 jours), même avec une carte grise pas encore à votre nom.`,`Attestation en 5 minutes.`]},{type:`stepflow`,ariaLabel:`Transition carte grise en 4 étapes : récupérer le véhicule, s'assurer, rouler avec le CPI, recevoir la carte grise définitive`,steps:[{icon:o,label:`Vous récupérez le véhicule`},{icon:i,label:`Assurance dès le 1er trajet`},{icon:n,label:`CPI : rouler 1 mois en France`},{icon:r,label:`Carte grise définitive par courrier`}]},{type:`text`,heading:`Peut-on rouler avant d'avoir sa carte grise définitive ?`,paragraphs:[`Oui. Quand vous faites votre demande d'immatriculation auprès de l'ANTS, vous obtenez un certificat provisoire d'immatriculation (CPI). Il vous autorise à circuler en France pendant 1 mois, le temps que la carte grise définitive soit imprimée et expédiée par courrier. À une condition incontournable : être assuré, car rouler sans assurance reste interdit, CPI ou pas.`],relatedLink:{text:`Assurer un véhicule acheté chez un particulier`,href:`/articles/assurer-vehicule-achete-chez-particulier`}},{type:`text`,heading:`L'assurance est-elle obligatoire avec un CPI ?`,paragraphs:[`Oui, et c'est indépendant de la carte grise. Tout véhicule qui circule doit avoir au minimum une responsabilité civile. Vous pouvez souscrire immédiatement avec votre CPI : votre attestation est émise tout de suite. C'est exactement le rôle de l'assurance temporaire, vous couvrir pendant la transition, en attendant de mettre en place votre assurance annuelle.`],relatedLink:{text:`Contrôlé sans assurance : risques, amende et que faire`,href:`/articles/controle-sans-assurance-risques-amende`}},{type:`text`,heading:`Que faire si les délais s'étirent ?`,paragraphs:[`Les délais de fabrication peuvent dépasser la validité du CPI. Côté immatriculation, vérifiez l'avancement sur votre espace ANTS et, si le délai est largement dépassé, contactez l'ANTS. Côté assurance, vous pouvez ajuster votre couverture temporaire (jusqu'à 90 jours) pour ne jamais rouler non assuré pendant l'attente.`],relatedLink:{text:`Pas encore de CPI ? Comment l'obtenir en urgence`,href:`/articles/carte-grise-urgence-cpi-immediat`}},{type:`text`,heading:`Quels documents pour souscrire ?`,paragraphs:[`Le permis, le CPI (ou la carte grise / le certificat de cession selon votre situation), un moyen de paiement. Souscription 100 % en ligne, attestation en 5 minutes.`],relatedLink:{text:`Carte grise pas encore à votre nom ? Comment assurer avec le certificat de cession ou le VIN`,href:`/articles/assurer-voiture-sans-carte-grise`}},{type:`text`,heading:`Quels documents reçoit-on avec l'assurance ?`,paragraphs:[`Depuis avril 2024, la carte verte n'existe plus. En France, la preuve d'assurance se fait à la plaque, via le Fichier des Véhicules Assurés (FVA). Le contrat comprend le Mémo Véhicule Assuré et la carte internationale d'assurance automobile, valable dans les 34 pays couverts.`],relatedLink:{text:`Véhicule ou permis étranger : assurance temporaire en France`,href:`/articles/assurance-temporaire-vehicule-etranger-france`}}],faqItems:[{q:`Peut-on rouler avec un certificat provisoire ?`,a:`Oui, le CPI autorise à circuler en France pendant 1 mois, en attendant la carte grise définitive.`},{q:`Faut-il une assurance avec un CPI ?`,a:`Oui, la RC est obligatoire dès le premier trajet, quel que soit le statut de la carte grise.`},{q:`Peut-on s'assurer sans la carte grise définitive ?`,a:`Oui, vous pouvez souscrire immédiatement avec le CPI.`},{q:`Que faire si la carte grise tarde ?`,a:`Vérifiez l'avancement sur l'ANTS ; côté assurance, prolongez votre couverture temporaire (jusqu'à 90 jours).`},{q:`Puis-je rouler à l'étranger avec un CPI ?`,a:`Le CPI classique autorise la circulation en France uniquement ; attendez la carte grise définitive pour l'étranger.`},{q:`Reçoit-on une carte verte ?`,a:`Non, elle a été supprimée. Mémo Véhicule Assuré + carte internationale (34 pays) ; contrôle à la plaque via le FVA.`}]}}));function f(){return(0,p.jsx)(c,{data:u})}var p;e((()=>{s(),d(),p=t()}))();export{f as default};